import java.util.Scanner;

public class MenuCalculator {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (true) {
            System.out.println("\n=== Calculator ===");
            System.out.println("1. Add  2. Subtract  3. Multiply  4. Divide  5. Exit");
            System.out.print("Choice: ");
            int choice = sc.nextInt();

            if (choice == 5) { System.out.println("Goodbye!"); break; }
            if (choice < 1 || choice > 4) { System.out.println("Invalid."); continue; }

            System.out.print("First  number: "); double a = sc.nextDouble();
            System.out.print("Second number: "); double b = sc.nextDouble();

            switch (choice) {
                case 1: System.out.printf("Result: %.4f%n", a + b); break;
                case 2: System.out.printf("Result: %.4f%n", a - b); break;
                case 3: System.out.printf("Result: %.4f%n", a * b); break;
                case 4:
                    if (b != 0) System.out.printf("Result: %.4f%n", a / b);
                    else System.out.println("Error: Division by zero.");
                    break;
            }
        }
        sc.close();
    }
}

