int main(void) {
    int    choice;
    double a, b;

    do {
        printf("\n=== Calculator ===\n");
        printf("1.Add  2.Subtract  3.Multiply  4.Divide  5.Exit\n");
        printf("Choice: ");
        scanf("%d", &choice);

        if (choice == 5) { printf("Goodbye!\n"); break; }
        if (choice < 1 || choice > 4) { printf("Invalid.\n"); continue; }

        printf("First number : "); scanf("%lf", &a);
        printf("Second number: "); scanf("%lf", &b);

        switch (choice) {
            case 1: printf("Result: %.4f\n", a + b); break;
            case 2: printf("Result: %.4f\n", a - b); break;
            case 3: printf("Result: %.4f\n", a * b); break;
            case 4:
                if (b != 0) printf("Result: %.4f\n", a / b);
                else printf("Error: Division by zero.\n");
                break;
        }
    } while (1);

    return 0;
}

