#include <stdio.h>
#include <string.h>
#define MAX 100
#define LEN 50
int main() {
    char sentence[] = "{{sentence}}";
    char words[MAX][LEN];
    int counts[MAX] = {0}, n = 0, i, j, found;
    char *tok = strtok(sentence, " \t\n");
    while (tok && n < MAX) {
        found = 0;
        for (i = 0; i < n; i++)
            if (strcmp(words[i], tok)==0) { counts[i]++; found=1; break; }
        if (!found) { strncpy(words[n], tok, LEN-1); counts[n++]=1; }
        tok = strtok(NULL, " \t\n");
    }
    printf("Word frequencies:\n");
    for (i = 0; i < n; i++)
        printf("  %s: %d\n", words[i], counts[i]);
    return 0;
}

