import java.util.Scanner;
public class TicTacToe {
    static char[][] board = new char[3][3];
    static void initBoard() { int n=1; for(int i=0;i<3;i++) for(int j=0;j<3;j++) board[i][j]=(char)('0'+n++); }
    static void printBoard() { for(int i=0;i<3;i++){ System.out.println(" "+board[i][0]+" | "+board[i][1]+" | "+board[i][2]); if(i<2)System.out.println("-----------"); } }
    static boolean checkWinner(char m) { for(int i=0;i<3;i++){ if(board[i][0]==m&&board[i][1]==m&&board[i][2]==m)return true; if(board[0][i]==m&&board[1][i]==m&&board[2][i]==m)return true; } return(board[0][0]==m&&board[1][1]==m&&board[2][2]==m)||(board[0][2]==m&&board[1][1]==m&&board[2][0]==m); }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        initBoard();
        char cur = 'X';
        for(int t=0;t<9;t++){
            printBoard();
            System.out.print("Player "+cur+" (1-9): ");
            int move = sc.nextInt();
            board[(move-1)/3][(move-1)%3] = cur;
            if(checkWinner(cur)){ printBoard(); System.out.println("Player "+cur+" wins!"); sc.close(); return; }
            cur = (cur=='X')?'O':'X';
        }
        printBoard(); System.out.println("Draw!"); sc.close();
    }
}

