import java.util.*;
public class ExpenseTracker {
    static List<String> descs=new ArrayList<>();
    static List<Double> amounts=new ArrayList<>();
    static List<String> cats=new ArrayList<>();
    static void add(String d,double a,String c){descs.add(d);amounts.add(a);cats.add(c);System.out.printf("Added: %s â€” %.2f (%s)%n",d,a,c);}
    static void summary(){
        if(descs.isEmpty()){System.out.println("No expenses.");return;}
        double total=0; Map<String,Double> ct=new TreeMap<>();
        for(int i=0;i<descs.size();i++){total+=amounts.get(i); ct.merge(cats.get(i),amounts.get(i),Double::sum);}
        System.out.printf("%nTotal spent: %.2f%nBy category:%n",total);
        ct.forEach((c,a)->System.out.printf("  %s: %.2f%n",c,a));
    }
    public static void main(String[] args){
        add("Lunch",120,"Food"); add("Bus fare",25,"Transport"); add("Book",350,"Education"); add("Dinner",180,"Food");
        summary();
    }
}

