import java.util.*;
public class RestaurantOrder{
    public static void main(String[] args){
        String[] names={"Adobo","Sinigang","Fried Rice","Juice"};
        double[] prices={180,220,80,60};
        Map<String,Integer> order=new LinkedHashMap<>();
        Scanner sc=new Scanner(System.in);
        System.out.println("=== Restaurant Menu ===");
        for(int i=0;i<4;i++)System.out.printf("  [%d] %-15s %.2f%n",i+1,names[i],prices[i]);
        while(true){System.out.print("\nAdd (1-4) or 0: ");int c=sc.nextInt();if(c==0)break;if(c>=1&&c<=4){order.merge(names[c-1],1,Integer::sum);System.out.println("Added "+names[c-1]);}}
        System.out.println("\n=== Bill ===");double total=0;
        for(Map.Entry<String,Integer>e:order.entrySet()){int idx=Arrays.asList(names).indexOf(e.getKey());double l=prices[idx]*e.getValue();total+=l;System.out.printf("  %dx %-15s %.2f%n",e.getValue(),e.getKey(),l);}
        System.out.printf("  TOTAL: %.2f%n",total);sc.close();
    }
}

