ROWS,COLS=6,7
board=[['.']*COLS for _ in range(ROWS)]
def print_board():
    for row in board:print(' '.join(row))
    print(' '.join(str(i+1) for i in range(COLS)))
def drop(col,p):
    for r in range(ROWS-1,-1,-1):
        if board[r][col]=='.':board[r][col]=p;return True
    return False
def check_win(p):
    for r in range(ROWS):
        for c in range(COLS-3):
            if all(board[r][c+i]==p for i in range(4)):return True
    for r in range(ROWS-3):
        for c in range(COLS):
            if all(board[r+i][c]==p for i in range(4)):return True
    for r in range(ROWS-3):
        for c in range(COLS-3):
            if all(board[r+i][c+i]==p for i in range(4)):return True
    for r in range(3,ROWS):
        for c in range(COLS-3):
            if all(board[r-i][c+i]==p for i in range(4)):return True
    return False
cur='X'
for _ in range(ROWS*COLS):
    print_board()
    col=int(input(f'Player {cur} col(1-7): '))-1
    if not(0<=col<COLS)or not drop(col,cur):print('Invalid.');continue
    if check_win(cur):print_board();print(f'Player {cur} wins!');break
    cur='O'if cur=='X'else'X'
else:print('Draw!')

