import java.util.*;
public class TextFileAnalyzer{
    public static void main(String[] args){
        String text="The quick brown fox jumps over the lazy dog.\nThe dog barked at the fox.\nThe fox ran away quickly.";
        String[] lines=text.split("\n");
        String[] words=text.toLowerCase().split("\\s+");
        int chars=text.replaceAll("[\\s]","").length();
        Map<String,Integer> freq=new TreeMap<>();
        for(String w:words){w=w.replaceAll("[^a-z]","");if(!w.isEmpty())freq.merge(w,1,Integer::sum);}
        List<Map.Entry<String,Integer>> sorted=new ArrayList<>(freq.entrySet());
        sorted.sort((a,b)->b.getValue()-a.getValue());
        System.out.println("=== Text Analysis ===");
        System.out.printf("Lines:%d  Words:%d  Chars:%d  Unique:%d%n",lines.length,words.length,chars,freq.size());
        System.out.println("\nTop 5 words:");
        for(int i=0;i<Math.min(5,sorted.size());i++)System.out.printf("  %-15s %d%n",sorted.get(i).getKey(),sorted.get(i).getValue());
    }
}

