#include <stdio.h>
#include <string.h>
#include <ctype.h>
#define MW 200
#define WL 40
int main(){
    char text[]="The quick brown fox jumps over the lazy dog.\nThe dog barked at the fox.\nThe fox ran away quickly.";
    int lines=1,chars=0,i;
    for(i=0;text[i];i++){if(text[i]=='\n')lines++;else if(!isspace((unsigned char)text[i]))chars++;}
    char tmp[sizeof(text)];strncpy(tmp,text,sizeof(text));
    char wlist[MW][WL];int wcount[MW]={0},n=0;
    for(char *tok=strtok(tmp," \t\n.,!?");tok;tok=strtok(NULL," \t\n.,!?")){
        char lw[WL];int k;for(k=0;tok[k]&&k<WL-1;k++)lw[k]=tolower((unsigned char)tok[k]);lw[k]=0;
        int found=0;for(i=0;i<n;i++)if(strcmp(wlist[i],lw)==0){wcount[i]++;found=1;break;}
        if(!found&&n<MW){strncpy(wlist[n],lw,WL-1);wcount[n++]=1;}
    }
    for(i=0;i<n-1;i++)for(int j=i+1;j<n;j++)if(wcount[j]>wcount[i]){int tc=wcount[i];wcount[i]=wcount[j];wcount[j]=tc;char tw[WL];strcpy(tw,wlist[i]);strcpy(wlist[i],wlist[j]);strcpy(wlist[j],tw);}
    printf("=== Text Analysis ===\nLines:%d  Chars:%d  Unique:%d\n\nTop 5 words:\n",lines,chars,n);
    for(i=0;i<5&&i<n;i++)printf("  %-15s %d\n",wlist[i],wcount[i]);
    return 0;
}

