class Account:
    _next=1001
    def __init__(self,owner,balance=0):
        self.id=Account._next;Account._next+=1
        self.owner=owner;self.balance=balance;self.history=[]
    def deposit(self,a):
        if a>0:self.balance+=a;self.history.append(f'+{a:.2f}')
    def withdraw(self,a):
        if a>self.balance:return False
        self.balance-=a;self.history.append(f'-{a:.2f}');return True
    def display(self): print(f'  Acc#{self.id} {self.owner:<12} Balance:{self.balance:>10.2f}')
def transfer(src,dst,amt):
    if src.withdraw(amt):dst.deposit(amt);print(f'Transferred {amt:.2f} from #{src.id} to #{dst.id}')
    else:print(f'Transfer failed: insufficient funds in #{src.id}')
accounts=[Account('Alice',5000),Account('Bob',3000),Account('Carlo',1000)]
accounts[0].deposit(1500);accounts[1].withdraw(500);transfer(accounts[0],accounts[2],2000)
print('=== Account Summary ===')
for a in accounts:a.display()

