    static class Account{static int nextId=1001;int id;String owner;double balance;Account(String o,double b){id=nextId++;owner=o;balance=b;}void deposit(double a){if(a>0)balance+=a;}boolean withdraw(double a){if(a>balance)return false;balance-=a;return true;}void display(){System.out.printf("  Acc#%d %-12s Balance:%10.2f%n",id,owner,balance);}}
    static void transfer(Account src,Account dst,double amt){if(src.withdraw(amt)){dst.deposit(amt);System.out.printf("Transferred %.2f from #%d to #%d%n",amt,src.id,dst.id);}else System.out.println("Transfer failed: insufficient funds in #"+src.id);}
    public static void main(String[] args){
        Account[] accounts={new Account("Alice",5000),new Account("Bob",3000),new Account("Carlo",1000)};
        accounts[0].deposit(1500);accounts[1].withdraw(500);transfer(accounts[0],accounts[2],2000);
        System.out.println("=== Account Summary ===");
        for(Account a:accounts)a.display();
    }
}

