#include <stdio.h>
#include <string.h>
typedef struct{int id;char owner[40];float balance;}Account;
int nextId=1001;
void init(Account *a,char *o,float b){a->id=nextId++;strncpy(a->owner,o,39);a->balance=b;}
void deposit(Account *a,float b){if(b>0)a->balance+=b;}
int withdraw(Account *a,float b){if(b>a->balance)return 0;a->balance-=b;return 1;}
void transfer(Account *s,Account *d,float a){if(withdraw(s,a)){deposit(d,a);printf("Transferred %.2f from #%d to #%d\n",a,s->id,d->id);}else printf("Transfer failed: #%d\n",s->id);}
void display(Account *a){printf("  Acc#%d %-12s Balance:%10.2f\n",a->id,a->owner,a->balance);}
int main(){
    Account accounts[3];
    init(&accounts[0],"Alice",5000);init(&accounts[1],"Bob",3000);init(&accounts[2],"Carlo",1000);
    deposit(&accounts[0],1500);withdraw(&accounts[1],500);transfer(&accounts[0],&accounts[2],2000);
    printf("=== Account Summary ===\n");
    int i;for(i=0;i<3;i++)display(&accounts[i]);
    return 0;
}

