import java.util.*;
public class CollectionsDemo {
    public static void main(String[] args) {
        // ArrayList â€” ordered, allows duplicates
        ArrayList<String> names = new ArrayList<>();
        names.add("Alice"); names.add("Bob"); names.add("Charlie");
        System.out.println(names);          // [Alice, Bob, Charlie]
        System.out.println(names.get(1));   // Bob
        names.remove("Bob");
        Collections.sort(names);
        System.out.println(names);          // [Alice, Charlie]

        // HashMap â€” key-value pairs
        HashMap<String, Integer> scores = new HashMap<>();
        scores.put("Alice", 95);
        scores.put("Bob",   88);
        System.out.println(scores.get("Alice")); // 95
        System.out.println(scores.containsKey("Charlie")); // false
        for (Map.Entry<String,Integer> e : scores.entrySet())
            System.out.println(e.getKey() + ": " + e.getValue());
    }
}

#include <stdio.h>
int main() {
    int {{var_name}} = {{var_value}};
    int *ptr = &{{var_name}};  // ptr stores the ADDRESS of {{var_name}}

    printf("Value:   %d\n",  {{var_name}});    // direct access
    printf("Address: %p\n",  (void*)ptr);      // memory address
    printf("Via ptr: %d\n",  *ptr);            // dereference

    // Modify through pointer
    *ptr = 99;
    printf("After:   %d\n", {{var_name}});     // {{var_name}} is now 99

    // Pointer arithmetic
    int arr[] = {10, 20, 30};
    int *p = arr;    // points to first element
    printf("%d %d %d\n", *p, *(p+1), *(p+2));
    return 0;
}

