#include <stdio.h>
#include <stdlib.h>
int main() {
    int n = {{size}};

    // Allocate array on the heap
    int *arr = (int*)malloc(n * sizeof(int));
    if (arr == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    // Use the array
    int i;
    for (i = 0; i < n; i++) arr[i] = (i + 1) * 10;
    for (i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");

    // ALWAYS free when done
    free(arr);
    arr = NULL;   // prevent dangling pointer

    // calloc: allocates AND zeroes memory
    int *zeros = (int*)calloc(n, sizeof(int));
    for (i = 0; i < n; i++) printf("%d ", zeros[i]);
    printf("\n");
    free(zeros);
    return 0;
}

