#include <stdio.h>    /* printf, scanf */
#include <math.h>     /* sqrt, pow, fabs */
#include <string.h>   /* strlen, strcpy, strcmp */
#include <stdlib.h>   /* abs, rand, srand */
#include <time.h>     /* time */

int main() {
    /* math.h */
    printf("sqrt(16) = %.1f\n", sqrt(16.0));
    printf("pow(2,8) = %.0f\n", pow(2, 8));

    /* string.h */
    char s[] = "Hello";
    printf("len = %lu\n", strlen(s));

    /* stdlib.h + time.h */
    srand((unsigned)time(NULL));
    printf("rand 1-10 = %d\n", rand() % 10 + 1);
    return 0;
}

